SELECT DISTINCT molecule_dictionary.chembl_id, molecule_dictionary.pref_name AS compound_name, compound_structures.canonical_smiles FROM docs INNER JOIN compound_records ON docs.doc_id = compound_records.doc_id INNER JOIN molecule_dictionary ON compound_records.molregno = molecule_dictionary.molregno INNER JOIN compound_structures ON molecule_dictionary.molregno = compound_structures.molregno WHERE docs.chembl_id = 'CHEMBL1123859' AND compound_structures.canonical_smiles IS NOT NULL ORDER BY molecule_dictionary.chembl_id, molecule_dictionary.pref_name, compound_structures.canonical_smiles;
